/* Force Multiplier 22.9.7 — Improvement Laboratory: Which statistical test and why? */
(function(){'use strict';
const L=window.FMImprovementTests,root=document.getElementById('ilApp'),KEY='fm-improvement-lab-2297';
if(!root||!L)return;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function empty(){return {view:'practice',idx:0,stage:0,correct:{},answer:null,message:null,selected:null,guide:false,topic:'All',card:null};}
let s=empty();try{const v=JSON.parse(localStorage.getItem(KEY)||'null');if(v&&typeof v==='object'&&v.correct)s={...empty(),...v};}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));}catch{}}
function update(p){Object.assign(s,p);save();render();}
const c=()=>L.caseByIndex(s.idx),t=()=>L.byId(c().id);
function titlebar(){return `<header class="ba-top"><a class="ba-round" href="./block-academy.html" aria-label="Return to Block Academy">←</a><div class="ba-logo"><b>IMPROVEMENT LAB</b><small>REVENGE OF THE NONNER</small></div><a class="ba-round" href="./index.html#analysis" aria-label="Original Analysis simulator">▦</a></header><div class="il-progress"><span>NON-NONNER <i>· test qualifications pending</i></span><b>${Object.keys(s.correct).length}/${L.CASES.length} tests</b></div>`}
function selector(){return `<nav class="il-tabs" aria-label="Improvement lab areas"><button data-mode="practice" class="${s.view==='practice'?'selected':''}">Practice</button><button data-mode="library" class="${s.view==='library'?'selected':''}">Test Library</button></nav>`}
function intro(){return `<section class="il-intro"><small>NO TIMER · OFFLINE · REPLAY ANY TEST</small><h1>Which test<br><em>and why?</em></h1><p>Keep the existing Analysis tools. Here, learn to choose a statistical test, state a defensible hypothesis, and interpret its result—without claiming that correlation proves causation.</p></section>`}
function questionTitle(){return ['1 · CHOOSE THE TEST','2 · STATE THE NULL HYPOTHESIS','3 · INTERPRET THE EVIDENCE','DEBRIEF'][s.stage]||''}
function guide(t){return `<section class="il-guide"><div class="il-tag">${esc(t.family)}</div><h2>${esc(t.name)}</h2><p><b>Question:</b> ${esc(t.question)}</p><p><b>Use it when:</b> ${esc(t.use)}</p><p><b>H₀:</b> ${esc(t.h0)}</p><p><b>Assumptions:</b> ${esc(t.assumptions)}</p><p><b>Do not overclaim:</b> ${esc(t.warning)}</p></section>`}
function options(){const opts=L.optionSet(s.idx,s.stage),q=s.stage;return `<div class="il-choice-grid" role="group" aria-label="Answer choices">${opts.map((o)=>`<button type="button" data-answer="${esc(o.id)}" class="il-choice ${s.selected===o.id?'chosen':''}">${q===0?'<span class="il-brick-icon">▦</span>':''}<span>${esc(o.label)}</span></button>`).join('')}</div>`}
function debrief(){const tc=t(),caseData=c();return `<div class="il-win"><strong>✓ TEST WALKTHROUGH COMPLETE</strong><p>${esc(caseData.effect)}</p></div>${guide(tc)}<div class="il-interpret"><h3>What the result does NOT tell you</h3><p>${esc(tc.warning)}</p><p>Statistical significance, practical importance, and cause are separate questions. Inspect effect size, confidence interval when applicable, measurement quality, and study design.</p></div><button class="ba-main-btn il-wide" data-next>Next test →</button><button class="ba-outlined" data-replay>↻ Try this test again</button>`}
function practice(){const x=c(),tc=t(),done=s.stage===3;return `${intro()}<section class="il-case"><div class="il-casehead"><span>${esc(tc.family)}</span><b>CASE ${s.idx+1}/${L.CASES.length}</b></div><h2>${esc(x.title)}</h2><p>${esc(x.scenario)}</p></section><div class="il-stage-head"><p class="ba-kicker">${questionTitle()}</p><div class="il-stage-dots">${[0,1,2].map(i=>`<span class="${i<s.stage?'done':''} ${i===s.stage?'current':''}"></span>`).join('')}</div></div>${done?debrief():`${s.stage===2?`<section class="il-sample"><small>FICTIONAL EXAMPLE OUTPUT — not computed from actual records</small><b>${esc(x.display)}</b><p>Prespecified α = 0.05. What conclusion follows under the test assumptions?</p></section>`:''}${s.stage===1?`<p class="il-prompt">Select the null hypothesis (H₀) that the test would evaluate.</p>`:''}${s.stage===0?`<p class="il-prompt">Move the appropriate test block onto the problem: tap a choice below.</p>`:''}${options()}${s.message?`<div class="ba-feedback ${s.message.ok?'good':'bad'}" role="status"><strong>${s.message.ok?'✓ CORRECT':'✕ TRY AGAIN'}</strong><p>${esc(s.message.text)}</p></div>`:''}${s.message?.ok?`<button class="ba-main-btn il-wide" data-advance>Continue →</button>`:''}<button class="ba-outlined" data-guide>${s.guide?'Hide the test explanation':'Explain this test'}</button>${s.guide?guide(tc):''}`}
<div class="il-bottom"><button data-prev>← Previous case</button><button data-skip>Next case →</button></div><section class="il-original"><b>Existing tools retained</b><p>The original rate practice, trends, correlation, differences, Fishbone and investigation workflow are unchanged. Use the full simulator for calculation and advanced investigation.</p><a href="./index.html#analysis">Open original Analysis simulator →</a><a href="./block-academy.html">Return to seven block missions →</a></section>`}
function library(){const topics=['All','Trends','Correlations','Differences','Counts & rates','Variation'],items=L.TESTS.filter(x=>s.topic==='All'||x.family===s.topic);return `${intro()}<section class="il-case"><h2>Statistical test field guide</h2><p>Browse the existing curriculum's trend, correlation, mean, rank, proportion, count, and variance tests. This is a selection and interpretation guide, not a replacement for the working statistics calculator.</p></section><div class="il-topics">${topics.map(x=>`<button data-topic="${esc(x)}" class="${s.topic===x?'selected':''}">${esc(x)}</button>`).join('')}</div>${items.map(x=>`<section class="il-test-card"><button data-card="${x.id}" aria-expanded="${s.card===x.id}"><span>${esc(x.family)}</span><strong>${esc(x.name)}</strong><small>${esc(x.question)}</small><b>${s.card===x.id?'−':'+'}</b></button>${s.card===x.id?guide(x):''}</section>`).join('')}<button class="ba-main-btn il-wide" data-mode="practice">Practice choosing the test →</button><section class="il-original"><b>Remember</b><p>A low p-value does not establish a large effect, a useful effect, or cause. Sample design and test assumptions matter. For actual inferential results, use the retained original tools.</p><a href="./index.html#analysis">Open full Analysis simulator →</a></section>`}
function render(){root.innerHTML=titlebar()+selector()+(s.view==='library'?library():practice());}
function answer(id){if(s.stage>2)return;const r=L.grade(s.idx,s.stage,id),tt=t();let explanation='';if(s.stage===0)explanation=r.ok?`${tt.name}: ${tt.use}`:`This question asks: ${tt.question} Check how the observations are grouped and measured.`;if(s.stage===1)explanation=r.ok?`Correct H₀: ${tt.h0}`:'The null hypothesis is a population-level statement about no effect, no association, or equal groups; not a claim that a sample must be constant.';if(s.stage===2)explanation=r.ok?`${c().display}. ${c().effect}`:'A p-value is not the probability H₀ is true, and it does not prove causation. Compare p to the prespecified α = 0.05.';update({selected:id,message:{ok:r.ok,text:explanation}})}
root.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;
 if(el.dataset.answer) return answer(el.dataset.answer);
 if(el.dataset.mode) return update({view:el.dataset.mode,message:null,guide:false});
 if(el.dataset.topic) return update({topic:el.dataset.topic,card:null});
 if(el.dataset.card) return update({card:s.card===el.dataset.card?null:el.dataset.card});
 if(el.hasAttribute('data-guide'))return update({guide:!s.guide});
 if(el.hasAttribute('data-advance')){if(!s.message?.ok||s.stage>2)return;const newStage=s.stage+1;if(newStage===3)s.correct[c().id]=true;return update({stage:newStage,message:null,selected:null,guide:false})}
 if(el.hasAttribute('data-next')||el.hasAttribute('data-skip'))return update({idx:(s.idx+1)%L.CASES.length,stage:0,message:null,selected:null,guide:false});
 if(el.hasAttribute('data-prev'))return update({idx:(s.idx-1+L.CASES.length)%L.CASES.length,stage:0,message:null,selected:null,guide:false});
 if(el.hasAttribute('data-replay'))return update({stage:0,message:null,selected:null,guide:false});
});
window.FMImprovementLab={getState:()=>JSON.parse(JSON.stringify(s)),answer,render,openCase:(i)=>update({idx:(i+L.CASES.length)%L.CASES.length,stage:0,message:null,selected:null}),getModel:()=>L};
render();
})();
